from datetime import datetime, timedelta

def find_next_palindrome_time(current_time):
    while True:
        if current_time.strftime('%H:%M') == current_time.strftime('%H:%M')[::-1]:
            return current_time
        current_time += timedelta(minutes=1)

def min_minutes_to_sleep(current_time_str):
    current_time = datetime.strptime(current_time_str, '%H:%M')
    next_palindrome_time = find_next_palindrome_time(current_time)
    time_difference = (next_palindrome_time - current_time).total_seconds() / 60
    return int(time_difference)

